<script setup lang="ts">
import { onBeforeUnmount,onMounted,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { api } from '../api'
const route=useRoute(),router=useRouter(),controller=new AbortController(),source=ref('manifest'),manifest=ref(''),available=ref(false),error=ref(''),sending=ref(false)
const now=new Date();const month=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`
const value=ref(JSON.stringify({mineId:'',status:'running',checkCycle:month,items:[{itemCode:'stop_work_unload'}]},null,2))
onBeforeUnmount(()=>controller.abort())
onMounted(async()=>{try{const [options,config]=await Promise.all([api.options(controller.signal),api.config(controller.signal)]);available.value=options.oceanbase_available;const item=config.config.items.find(i=>i.enabled);value.value=JSON.stringify({mineId:options.allowed_mines.length===1?options.allowed_mines[0]:'',status:'running',checkCycle:month,items:[{itemCode:item?.itemCode || 'stop_work_unload'}]},null,2);if(route.query.from){const previous=await api.task(String(route.query.from),controller.signal);if(previous.request){value.value=JSON.stringify(previous.request,null,2);manifest.value=String(previous.request.manifestPath || '');source.value=previous.request.dataSource==='oceanbase'?'oceanbase':'manifest';}}}catch(e){if(!controller.signal.aborted)error.value=e instanceof Error?e.message:'配置未载入'}})
async function submit(){sending.value=true;error.value='';try{const body=JSON.parse(value.value);if(!body || typeof body!=='object' || Array.isArray(body))throw new Error('任务 JSON 必须是对象');body.dataSource=source.value;if(source.value==='manifest')body.manifestPath=manifest.value.trim() || body.manifestPath;if(source.value==='manifest'&&!body.manifestPath)throw new Error('请选择本地资料清单，或在 JSON 中提供 manifestPath');const result=await api.trigger(body,controller.signal);const record=result.task_key || result.items?.[0]?.run_id;if(record)router.push(`/tasks/${encodeURIComponent(record)}`)}catch(e){if(!controller.signal.aborted)error.value=e instanceof Error?e.message:'任务提交失败'}finally{sending.value=false}}
</script>
<template><section class="page-stack"><div class="page-intro"><div><h2>手动触发任务</h2><p class="muted">提交任务 JSON 后自动进入任务详情。每次提交会保留独立的执行记录。</p></div></div><div class="trigger-layout"><div class="panel trigger-form"><div class="form-grid"><label class="span-all">取数方式<select v-model="source"><option value="manifest">已有本地资料清单</option><option value="oceanbase" :disabled="!available">{{ available?'OceanBase 清单查询':'OceanBase（未配置）' }}</option></select></label><label v-if="source==='manifest'" class="span-all">本地 manifest 绝对路径<input v-model="manifest" placeholder="也可在 JSON 中提供 manifestPath" /></label></div><label for="task-json">任务 JSON</label><textarea id="task-json" v-model="value" spellcheck="false" rows="15" /><p class="field-help">mineId 和 items 必填；提供 checkCycle 时按该周期取数，省略时按当前月。resultCallbackUrl 可保留在报文中，本地调试不投递结果。</p><p v-if="error" class="error-banner">{{ error }}</p><button class="button primary full" :disabled="sending" @click="submit">{{ sending?'正在受理…':'接收任务并执行' }}</button></div><aside class="panel trigger-guide"><h3>本次将执行</h3><ol><li>校验任务与检查项配置</li><li>冻结资料范围和版本</li><li>解析文件与识别扫描页</li><li>提取事实，核验规则</li><li>查看结论和引用证据</li></ol><div class="callout">结果保留在本地<br><small>callbackMode = none</small></div></aside></div></section></template>
